<?php /** 근태 설정 저장 */ use App\Core\Db; require_once __DIR__.'/../attendance/common.php'; if(!attendance_is_manager())exit; if(!csrf_check(isset($_POST['_csrf'])?$_POST['_csrf']:''))exit; $pdo=Db::pdo(); $now=attendance_now(); foreach(array('standard_weekly_hours','max_weekly_hours') as $k){$v=trim((string)$_POST[$k]); $st=$pdo->prepare("REPLACE INTO cpms_attendance_settings(setting_key,setting_value,updated_at) VALUES(:k,:v,:u)");$st->execute(array(':k'=>$k,':v'=>$v,':u'=>$now));} header('Location: ?r=관리&tab=attendance&atab=settings');